import math
        import random
        import time

        LANGUAGE_WRAPPER = 'In base 10, consider all positive integers N with exactly {digit_count} digits. Let S be the set of such integers that simultaneously satisfy all of the following:\n- N is divisible by each of its nonzero digits;\n- N is divisible by the sum of its digits;\n- the greatest common divisor of its nonzero digits equals {g_target};\n- the set of nonzero digits of N contains at least {min_distinct} distinct values.\nFind the sum of all integers in S.'

        class _RNGShim:
    def __init__(self, seed: int):
        import random as _random
        self._seed = int(seed)
        self._r = _random.Random(self._seed)

    def random(self): return self._r.random()
    def uniform(self, a, b): return self._r.uniform(a, b)
    def randint(self, a, b): return self._r.randint(a, b)
    def randrange(self, *args): return self._r.randrange(*args)
    def choice(self, seq): return self._r.choice(seq)
    def choices(self, population, weights=None, cum_weights=None, k: int = 1):
        return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
    def sample(self, population, k: int): return self._r.sample(population, k)
    def shuffle(self, x):
        self._r.shuffle(x)
        return x
    def getrandbits(self, k: int): return self._r.getrandbits(k)

        from math import gcd

def _digits(n):
    return [int(c) for c in str(n)]

def _solutions(digit_count, min_distinct, g_target):
    lo = 10**(digit_count-1)
    hi = 10**digit_count - 1
    sols = []
    for N in range(lo, hi+1):
        ds = _digits(N)
        s = sum(ds)
        if s == 0:
            continue  # impossible for positive N
        nz = [d for d in ds if d != 0]
        if len(set(nz)) < min_distinct:
            continue
        if not nz:
            continue
        g = 0
        for d in nz:
            g = gcd(g, d)
        if g != g_target:
            continue
        # Divisible by sum of digits
        if N % s != 0:
            continue
        # Divisible by each nonzero digit
        ok = True
        for d in set(nz):
            if N % d != 0:
                ok = False
                break
        if not ok:
            continue
        sols.append(N)
    return sols


def generator(rng):
    # Try randomized parameters, ensure nontrivial instance
    candidates = []
    # Create a shuffled list of reasonable parameter triples
    param_pool = [(3, 2, g) for g in [1,2,3]] + [(4, 2, g) for g in [1,2,3]] + [(3, 3, g) for g in [1,2]]
    rng.shuffle(param_pool)
    # Attempt up to 50 randomized trials
    for _ in range(50):
        # With some probability, pick from pool; otherwise random pick from ranges
        if rng.random() < 0.7 and param_pool:
            digit_count, min_distinct, g_target = param_pool.pop()
        else:
            digit_count = rng.choice([3,4])
            min_distinct = rng.choice([2,3])
            g_target = rng.choice([1,2,3])
        sols = _solutions(digit_count, min_distinct, g_target)
        cnt = len(sols)
        # Difficulty and validity guardrails
        if cnt >= 3 and cnt <= 800:
            return {
                'digit_count': digit_count,
                'min_distinct': min_distinct,
                'g_target': g_target
            }
        else:
            candidates.append((digit_count, min_distinct, g_target, cnt))
    # Fallback: choose the best candidate by closeness to target difficulty
    if candidates:
        # Prefer cnt >= 3; otherwise pick the max cnt
        valid = [c for c in candidates if c[3] >= 3]
        picked = None
        if valid:
            # Pick with smallest cnt above threshold to avoid triviality
            picked = sorted(valid, key=lambda x: x[3])[0]
        else:
            picked = sorted(candidates, key=lambda x: -x[3])[0]
        dc, md, gt, _ = picked
        return {
            'digit_count': dc,
            'min_distinct': md,
            'g_target': gt
        }
    # Ultimate fallback to a known-good configuration
    return {
        'digit_count': 3,
        'min_distinct': 2,
        'g_target': 1
    }

